(function(){'use strict';function ready(){const title=document.getElementById('teaching-lesson'),camera=document.getElementById('teaching-camera'),list=document.getElementById('teaching-cues'),status=document.getElementById('teaching-status');if(!title||!camera||!list)return;const cues=[];document.getElementById('teaching-cue-add').addEventListener('click',()=>{if(cues.length>=20){status.textContent='Maximum 20 camera cues per outline.';return;}const cue={camera:camera.value,lesson:title.value.trim()||'Untitled lesson'};cues.push(cue);const li=document.createElement('li');li.textContent=cue.camera+' — '+cue.lesson;list.appendChild(li);status.textContent='Camera cue added to lesson plan; live camera was not switched.';});document.getElementById('teaching-notes-copy').addEventListener('click',async()=>{const outline=['Lesson: '+(title.value.trim()||'Untitled lesson'),'Camera cues:',...cues.map((c,i)=>(i+1)+'. '+c.camera+' — '+c.lesson)].join('\n');try{await navigator.clipboard.writeText(outline);status.textContent='Lesson outline copied.';}catch{status.textContent='Clipboard unavailable. Use a secure browser context.';}});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready);else ready();}());